// Drei Abfragen zu CSV-Texten zusammenbauen, wie sie das Portal erwartet (Trennzeichen ;, UTF-8, Kopfzeile).
function csv(rows) {
  if (!rows.length) return '';
  const spalten = Object.keys(rows[0].json);
  const feld = (v) => {
    if (v === null || v === undefined) return '';
    let s = v instanceof Date ? v.toISOString().slice(0, 10) : String(v);
    s = s.replace(/\r?\n/g, ' ');
    return /[;"]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  return [spalten.join(';'), ...rows.map((r) => spalten.map((c) => feld(r.json[c])).join(';'))].join('\n') + '\n';
}
const buchungen = $('EP3 Buchungen').all();
const kunden = $('EP3 Kunden').all();
const texte = $('EP3 Texte').all();
const events = $('EP3 Events').all();
return [{ json: {
  bookings_csv: csv(buchungen),
  kunden_csv: csv(kunden),
  texte_csv: csv(texte),
  events_csv: csv(events),
  anzahl: { buchungen: buchungen.length, kunden: kunden.length, texte: texte.length, events: events.length },
  quelle: $('Webhook').first().json.body?.quelle ?? null,
  // angeforderter Zeitraum (Portal: „Ab Datum nachladen“) – nur zurückmelden, wenn er in „EP3 Buchungen“ angewendet wurde
  ab: /^\d{4}-\d{2}-\d{2}$/.test(String($('Webhook').first().json.body?.ab ?? '')) ? $('Webhook').first().json.body.ab : null,
} }];
